/**
 * reconciliationPdf.ts — a completed medication reconciliation as an
 * agency-branded, auditable record.
 *
 * The checklist compares the active orders against the current MAR medication
 * list; each line records continue / change / stop, whether it was a
 * discrepancy, and the nurse's note. Decisions never rely on colour alone —
 * every line spells out its decision and flags discrepancies in words — so the
 * printed page reads the same in black and white. Every page carries the
 * "Digital record generated by Complyrer" mark via stampRecordMark.
 */
import { jsPDF } from "jspdf";
import { stampRecordMark, startBrandedDoc } from "./brandHeader";
import {
  RECONCILIATION_DECISION_LABEL,
  RECONCILIATION_TRIGGER_LABEL,
} from "../data/medicationOrders";
import type { MedicationReconciliationView } from "../data/types";

const PAGE_BOTTOM = 740;

function slug(value: string) {
  return value
    .toLowerCase()
    .replaceAll(/[^a-z0-9]+/g, "-")
    .replaceAll(/(^-|-$)/g, "");
}

export function reconciliationFileName(
  individualName: string,
  generatedAt: string,
) {
  const date = generatedAt.slice(0, 10);
  return `complyrer-medication-reconciliation-${slug(individualName) || "individual"}-${date}.pdf`;
}

export function buildReconciliationPdf(input: {
  agencyName: string;
  individualName: string;
  siteName: string;
  reconciliation: MedicationReconciliationView;
  generatedAt: string;
  logoDataUrl?: string | null;
}) {
  const { reconciliation: recon } = input;
  const { doc, margin, y: startY } = startBrandedDoc("Medication reconciliation", {
    agencyName: input.agencyName,
    logoDataUrl: input.logoDataUrl,
  });
  const contentWidth = 504;
  let y = startY;

  const ensureSpace = (needed: number) => {
    if (y + needed > PAGE_BOTTOM) {
      doc.addPage();
      y = 64;
    }
  };

  const writePair = (label: string, value: string) => {
    ensureSpace(30);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(9);
    doc.setTextColor(95, 81, 69);
    doc.text(label, margin, y);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(11);
    doc.setTextColor(36, 30, 24);
    const lines = doc.splitTextToSize(value || "—", contentWidth);
    doc.text(lines, margin, y + 12);
    y += 12 + lines.length * 14 + 6;
  };

  const sectionTitle = (title: string) => {
    ensureSpace(42);
    y += 6;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.setTextColor(47, 70, 48);
    doc.text(title, margin, y);
    y += 18;
  };

  const fmt = (iso: string | null) =>
    iso
      ? new Date(iso).toLocaleString("en-US", {
          month: "short",
          day: "numeric",
          year: "numeric",
          hour: "numeric",
          minute: "2-digit",
        })
      : "—";

  writePair("Individual", input.individualName);
  writePair("Site", input.siteName || "—");
  writePair("Reason for reconciliation", RECONCILIATION_TRIGGER_LABEL[recon.trigger]);
  writePair(
    "Status",
    recon.status === "completed" ? "Completed and signed off" : "In progress",
  );
  writePair("Started by", `${recon.startedByName} · ${fmt(recon.startedAt)}`);

  const discrepancyCount = recon.items.filter((item) => item.discrepancy).length;
  sectionTitle(
    `Medication decisions (${recon.items.length} line${
      recon.items.length === 1 ? "" : "s"
    }, ${discrepancyCount} discrepanc${discrepancyCount === 1 ? "y" : "ies"})`,
  );

  if (recon.items.length === 0) {
    ensureSpace(20);
    doc.setFont("helvetica", "italic");
    doc.setFontSize(11);
    doc.setTextColor(36, 30, 24);
    doc.text("No medication lines were recorded.", margin, y);
    y += 18;
  } else {
    let index = 1;
    for (const item of recon.items) {
      const header = `${index}. ${item.medicationLabel}`;
      const headerLines = doc.splitTextToSize(header, contentWidth);
      ensureSpace(headerLines.length * 14 + 30);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(11);
      doc.setTextColor(36, 30, 24);
      doc.text(headerLines, margin, y);
      y += headerLines.length * 14;

      const decision = `Decision: ${RECONCILIATION_DECISION_LABEL[item.decision]}${
        item.discrepancy ? " · Discrepancy flagged" : ""
      }`;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(10);
      doc.setTextColor(95, 81, 69);
      doc.text(decision, margin + 12, y + 12);
      y += 24;

      if (item.note.trim()) {
        const noteLines = doc.splitTextToSize(`Note: ${item.note.trim()}`, contentWidth - 12);
        ensureSpace(noteLines.length * 13 + 6);
        doc.setFontSize(10);
        doc.setTextColor(36, 30, 24);
        doc.text(noteLines, margin + 12, y);
        y += noteLines.length * 13 + 4;
      }
      y += 6;
      index += 1;
    }
  }

  sectionTitle("Nurse sign-off");
  writePair(
    "Signed off by",
    recon.signedOffByName
      ? `${recon.signedOffByName} · ${fmt(recon.signedOffAt)}`
      : "Not yet signed off",
  );
  writePair("Sign-off note", recon.signOffNote || "—");

  stampRecordMark(doc, {
    documentId: `reconciliation-${recon.id}`,
    generatedAt: input.generatedAt,
  });
  return doc as jsPDF;
}
